  .p-timeline-cards .card { flex: 1 1 0; background: color-mix(in srgb, var(--accent) 8%, transparent); border-radius: 0.5em; padding: 0.32em 0.65em; }
  .p-timeline-cards .card .n { display: inline-flex; align-items: center; justify-content: center; width: 1.7em; height: 1.7em; border-radius: 50%; background: var(--accent); color: #fff; font-size: 0.95em; font-weight: 800; line-height: 1; }
  .p-timeline-cards .card .l { font-size: 0.85em; color: var(--text); margin-top: 0.2em; font-weight: 600; line-height: 1.2; }
  .p-timeline-cards .card .s { font-size: 0.7em; color: var(--muted); margin-top: 0.15em; font-style: italic; }
  .p-timeline-cards .arrow { flex: 0 0 1em; font-size: 1.4em; color: var(--accent); display: flex; align-items: center; justify-content: center; font-weight: 700; }
  /* P16c — TIMELINE PILLS: badges on a horizontal accent rail */
  .p-timeline-pills { position: relative; padding: 0.8em 0 0.4em 0; }
  .p-timeline-pills .rail { position: absolute; top: 1.4em; left: 4%; right: 4%; height: 2px; background: var(--accent); }
  .p-timeline-pills .pills { display: flex; justify-content: space-between; gap: 0.3em; position: relative; }
